function nest(flat, status, note) {
  const out = { _meta: { status, note } };
  for (const [key, value] of Object.entries(flat)) {
    const parts = key.split(".");
    let node = out;
    for (const part of parts.slice(0, -1)) {
      node[part] ??= {};
      node = node[part];
    }
    node[parts.at(-1)] = value;
  }
  return out;
}

for (const [code, flat] of Object.entries({ mr, bn, ta, te })) {
  const target = join(MESSAGES, `${code}.json`);
  writeFileSync(target, JSON.stringify(nest(flat, "draft", NOTE), null, 2) + "\n", "utf8");
  console.log(`${code}.json written — ${Object.keys(flat).length} keys`);
}
